import { useState } from "react";
import * as Yup from "yup";
// form
import { useForm } from "react-hook-form";
import { yupResolver } from "@hookform/resolvers/yup";
// mui
import { Stack, Card, Container, Button, Divider, Alert } from "@mui/material";
import HeaderBreadcrumbs from "src/components/HeaderBreadcrumbs";
// components
import Iconify from "src/components/Iconify";
import Page from "src/components/Page";
import { FormProvider, RHFTextField } from "src/components/hook-form";
// hooks
import useSettings from "src/hooks/useSettings";
// routes
import { PATH_DASHBOARD } from "src/routes/paths";

export default function Factorial() {
  const { themeStretch } = useSettings();

  const [p, setP] = useState(null);
  const [a, setA] = useState(null);
  const [c, setC] = useState(null);

  // Hook form
  const FormSchema = Yup.object().shape({
    n: Yup.number().typeError("").integer("").min(0, "").required(""),
  });

  const AFormSchema = Yup.object().shape({
    k: Yup.number().typeError("").integer("").min(0, "").required(""),
    n: Yup.number().typeError("").integer("").min(0, "").required(""),
  });

  const CFormSchema = Yup.object().shape({
    k: Yup.number().typeError("").integer("").min(0, "").required(""),
    n: Yup.number().typeError("").integer("").min(0, "").required(""),
  });

  const defaultValues = {
    n: "",
  };

  const defaultAValues = {
    k: "",
    n: "",
  };

  const defaultCValues = {
    k: "",
    n: "",
  };

  const methods = useForm({
    resolver: yupResolver(FormSchema),
    defaultValues,
  });

  const Amethods = useForm({
    resolver: yupResolver(AFormSchema),
    defaultValues: defaultAValues,
  });

  const Cmethods = useForm({
    resolver: yupResolver(CFormSchema),
    defaultValues: defaultCValues,
  });

  const { getValues, handleSubmit } = methods;

  const getValuesA = Amethods.getValues;
  const handleSubmitA = Amethods.handleSubmit;

  const getValuesC = Cmethods.getValues;
  const handleSubmitC = Cmethods.handleSubmit;

  const onSubmit = ({ n }) => {
    setP(factorial(n));
  };

  const onSubmitA = ({ k, n }) => {
    if (k > n) {
      setA(-1);
    } else {
      setA(factorial(n) / factorial(n - k));
    }
  };

  const onSubmitC = ({ k, n }) => {
    if (k > n) {
      setC(-1);
    } else {
      setC(factorial(n) / factorial(n - k) / factorial(k));
    }
  };

  return (
    <Page title="Tính toán chung">
      <Container maxWidth={themeStretch ? false : "lg"}>
        <HeaderBreadcrumbs
          heading="Tính toán chung"
          links={[
            {
              name: "Thống kê và Xác suất",
              href: PATH_DASHBOARD.thongKeVaXacSuat.root,
            },
            {
              name: "Xác suất",
              href: PATH_DASHBOARD.thongKeVaXacSuat.xacSuat.root,
            },
            { name: "Tính toán chung" },
          ]}
        />
        <Stack spacing={2}>
          <Card>
            <FormProvider methods={methods} onSubmit={handleSubmit(onSubmit)}>
              <Stack
                spacing={2}
                direction={{ xs: "column", sm: "row" }}
                sx={{ py: 2.5, px: 3 }}
              >
                <RHFTextField
                  name="n"
                  type="number"
                  label="N = "
                  fullWidth
                  InputLabelProps={{
                    shrink: true,
                  }}
                  sx={{
                    maxWidth: { sm: 200 },
                  }}
                />
                <Divider orientation="vertical" flexItem />
                <Button
                  type="submit"
                  fullWidth
                  variant="contained"
                  startIcon={<Iconify icon={"ic:outline-calculate"} />}
                  sx={{
                    maxWidth: { sm: 160 },
                    textTransform: "capitalize",
                  }}
                >
                  Tính giai thừa
                </Button>
                {p && (
                  <Alert>
                    P({getValues("n")}) = {p}
                  </Alert>
                )}
              </Stack>
            </FormProvider>
          </Card>
          <Card>
            <FormProvider
              methods={Amethods}
              onSubmit={handleSubmitA(onSubmitA)}
            >
              <Stack
                spacing={2}
                direction={{ xs: "column", sm: "row" }}
                sx={{ py: 2.5, px: 3 }}
              >
                <RHFTextField
                  name="k"
                  type="number"
                  label="K = "
                  fullWidth
                  InputLabelProps={{
                    shrink: true,
                  }}
                  sx={{
                    maxWidth: { sm: 200 },
                  }}
                />
                <RHFTextField
                  name="n"
                  type="number"
                  label="N = "
                  fullWidth
                  InputLabelProps={{
                    shrink: true,
                  }}
                  sx={{
                    maxWidth: { sm: 200 },
                  }}
                />
                <Divider orientation="vertical" flexItem />
                <Button
                  type="submit"
                  fullWidth
                  variant="contained"
                  startIcon={<Iconify icon={"ic:outline-calculate"} />}
                  sx={{
                    maxWidth: { sm: 160 },
                    textTransform: "capitalize",
                  }}
                >
                  Tính chỉnh hợp
                </Button>
                {a &&
                  (a < 0 ? (
                    <Alert variant="outlined" severity="error">
                      K phải bé hơn hoặc bằng N
                    </Alert>
                  ) : (
                    <Alert>
                      A(K = {getValuesA("k")}, N = {getValuesA("n")}) = {a}
                    </Alert>
                  ))}
              </Stack>
            </FormProvider>
          </Card>
          <Card>
            <FormProvider
              methods={Cmethods}
              onSubmit={handleSubmitC(onSubmitC)}
            >
              <Stack
                spacing={2}
                direction={{ xs: "column", sm: "row" }}
                sx={{ py: 2.5, px: 3 }}
              >
                <RHFTextField
                  name="k"
                  type="number"
                  label="K = "
                  fullWidth
                  InputLabelProps={{
                    shrink: true,
                  }}
                  sx={{
                    maxWidth: { sm: 200 },
                  }}
                />
                <RHFTextField
                  name="n"
                  type="number"
                  label="N = "
                  fullWidth
                  InputLabelProps={{
                    shrink: true,
                  }}
                  sx={{
                    maxWidth: { sm: 200 },
                  }}
                />
                <Divider orientation="vertical" flexItem />
                <Button
                  type="submit"
                  fullWidth
                  variant="contained"
                  startIcon={<Iconify icon={"ic:outline-calculate"} />}
                  sx={{
                    maxWidth: { sm: 160 },
                    textTransform: "capitalize",
                  }}
                >
                  Tính tổ hợp
                </Button>
                {c &&
                  (c < 0 ? (
                    <Alert variant="outlined" severity="error">
                      K phải bé hơn hoặc bằng N
                    </Alert>
                  ) : (
                    <Alert>
                      A(K = {getValuesC("k")}, N = {getValuesC("n")}) = {c}
                    </Alert>
                  ))}
              </Stack>
            </FormProvider>
          </Card>
        </Stack>
      </Container>
    </Page>
  );
}

function factorial(n) {
  let ans = 1;
  for (let i = 1; i <= n; i++) {
    ans *= i;
  }
  return ans;
}
